declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../admin/includes/auth.php';
$id=(int)($_GET['id']??$_POST['id']??0);$errors=[];$project=['title'=>'','slug'=>'','category'=>'','client_name'=>'','industry'=>'','project_type'=>'','project_duration'=>'','project_scope'=>'','objectives'=>'','short_description'=>'','challenge'=>'','strategy'=>'','solution'=>'','key_features'=>'','results'=>'','technologies'=>'','featured_image'=>'','gallery'=>'','live_url'=>'','github_url'=>'','meta_title'=>'','meta_description'=>'','is_featured'=>0,'is_published'=>1];
if($id){$stmt=db()->prepare('SELECT * FROM projects WHERE d=?');$stmt->execute([$id]);$found=$stmt->fetch();if($found)$project=array_merge($project,array_map(static fn($v)=>$v??'',$found));}
if($_SERVER['REQUEST_METHOD']==='POST'){foreach(array_keys($project) as $key){if(isset($_POST[$key]))$project[$key]=is_string($_POST[$key])?trim($_POST[$key]):$_POST[$key];}$project['is_featured']=isset($_POST['is_featured'])?1:0;$project['is_published']=isset($_POST['is_published'])?1:0;if($project['title']===''||$project['category']===''||$project['short_description']==='')$errors[]='Title, category and short description are required.';if($project['slug']==='')$project['slug']=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$project['title']),'-'));if($project['gallery']!==''){json_decode($project['gallery'],true);if(json_last_error()!==JSON_ERROR_NONE)$errors[]='Gallery must be valid JSON, e.g. ["assets/img/project-1.jpg","assets/img/project-2.jpg"].';}if(!$errors){$fields=['title','slug','category','client_name','industry','project_type','project_duration','project_scope','objectives','short_description','challenge','strategy','solution','key_features','results','technologies','featured_image','gallery','live_url','github_url','meta_title','meta_description','is_featured','is_published'];$set=implode(',',array_map(fn($f)=>$f.'=?',$fields));$values=array_map(fn($f)=>$project[$f],$fields);if($id){db()->prepare("UPDATE projects SET $set WHERE d=?")->execute([...$values,$id]);}else{db()->prepare('INSERT INTO projects ('.implode(',',$fields).') VALUES ('.implode(',',array_fill(0,count($fields),'?')).')')->execute($values);}header('Location: projects.php');exit;}}
